def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    seen=set(); holes=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=0 or (r,c) in seen: continue
            q=[(r,c)]; seen.add((r,c)); comp=[]; edge=False
            for y,x in q:
                comp.append((y,x)); edge |= y==0 or y==h-1 or x==0 or x==w-1
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx]==0 and (yy,xx) not in seen:
                        seen.add((yy,xx)); q.append((yy,xx))
            if not edge: holes.append(comp)
    # Label 8-connected components of the frame color.
    seen1=set(); active=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=1 or (r,c) in seen1: continue
            q=[(r,c)]; seen1.add((r,c)); comp=[]
            for y,x in q:
                comp.append((y,x))
                for dy in (-1,0,1):
                    for dx in (-1,0,1):
                        yy,xx=y+dy,x+dx
                        if (dy or dx) and 0<=yy<h and 0<=xx<w and grid[yy][xx]==1 and (yy,xx) not in seen1:
                            seen1.add((yy,xx)); q.append((yy,xx))
            active.append(comp)
    active_comps=[]
    hole_cells={p for comp in holes for p in comp}
    for comp in active:
        enclosed=any((y+dy,x+dx) in hole_cells for y,x in comp for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)) if 0<=y+dy<h and 0<=x+dx<w)
        if enclosed: active_comps.append(comp)
    # Paint boundary layer inside each enclosed zero region.
    for comp in holes:
        for y,x in comp:
            if any(0<=y+dy<h and 0<=x+dx<w and grid[y+dy][x+dx]==1 for dy in (-1,0,1) for dx in (-1,0,1) if dy or dx):
                out[y][x]=3
    # Paint the one-cell 8-neighbour halo outside each closed frame.
    for comp in active_comps:
        for y,x in comp:
            for dy in (-1,0,1):
                for dx in (-1,0,1):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx]==0 and (yy,xx) not in hole_cells:
                        out[yy][xx]=2
    return out

